  Future<void> _loadAllData() async {
    isLoading = true;
    update();
    try {
      await Future.wait([
        _loadBanners(),
        _loadCategories(),
        _loadFeaturedStores(),
        _loadFeaturedProducts(),
        _loadFlashSale(),
        _loadTrending(),
        _loadNewArrivals(),
        _loadOffers(),
        _loadRecommended(),
      ]);

      await Future.wait([
        _loadFavorites(),
        loadAllProducts(reset: true),
      ]);
    } catch (error, stackTrace) {
      debugPrint('Buyer home loading failed: $error');
      debugPrintStack(stackTrace: stackTrace);
    } finally {
      isLoading = false;
      update();
    }
  }

  Future<void> _loadBanners() async {
    final result = await _ds.getBanners();
    result.fold(
      (_) {},
      (res) {
        final list = _extractList(res);
        if (list.isNotEmpty) {
          banners = list.map(BuyerBannerItem.fromJson).toList();
        } else {
        }
      },
    );
  }

  Future<void> _loadCategories() async {
    final result = await _ds.getCategories();
    result.fold(
      (_) {},
      (res) {
        final list = _extractList(res);
        if (list.isNotEmpty) {
          categories = [
            BuyerCategoryItem(
              id: 'all',
              label: 'all_categories'.tr,
              icon: Icons.apps_rounded,
              colorHex: '#CC5813',
            ),
            ...list.map(BuyerCategoryItem.fromJson),
          ];
          selectedCategoryId ??= categories.first.id;
        } else {
        }
      },
    );
  }

